# The default nginx site for Day 36: serve /var/www/html on port 80.
# IPv4 only: the lab's Docker network has no IPv6.
server {
    listen 80 default_server;
    root /var/www/html;
    index index.html;

    # Do not show the nginx version in headers and error pages.
    server_tokens off;
}

