# {{ ansible_managed }}
# Rendered for {{ inventory_hostname }} ({{ ansible_facts['distribution'] }} {{ ansible_facts['distribution_version'] }}).
[Unit]
Description=hello-devops {{ hello_devops_version }}
After=network-online.target
Wants=network-online.target

[Service]
User={{ hello_devops_user }}
Group={{ hello_devops_user }}
WorkingDirectory={{ hello_devops_dir }}
# APP_VERSION, GREETING and the token come from this file (mode 0640).
EnvironmentFile=/etc/hello-devops.env
ExecStart={{ hello_devops_dir }}/venv/bin/gunicorn --bind 0.0.0.0:{{ hello_devops_port }} --workers {{ hello_devops_workers }} app:app
Restart=on-failure

[Install]
WantedBy=multi-user.target

# {{ ansible_managed }}
APP_VERSION={{ hello_devops_version }}
GREETING={{ hello_devops_greeting }}
{% if hello_devops_api_token %}
# A fake secret from Ansible Vault. hello-devops does not read it.
HELLO_API_TOKEN={{ hello_devops_api_token }}
{% endif %}

# {{ ansible_managed }}
# nginx on {{ inventory_hostname }}: send each request to one of the web servers.
# Docker's DNS knows the names web1 and web2. On real servers, use their
# private IP addresses or DNS names instead.
upstream hello_devops {
    # Shared memory, so all nginx worker processes take turns together.
    zone hello_devops 64k;
{% for host in groups['web'] %}
    server {{ host }}:{{ hostvars[host]['hello_devops_port'] }};
{% endfor %}
}

server {
    listen 80 default_server;
    server_tokens off;

    location / {
        proxy_pass http://hello_devops;
        proxy_set_header Host $host;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
    }
}
